package com.vabugeode.app.achievements

/** Новые условия — по журналу; названия не утверждают, что распознаны здания или тип местности. */
internal fun expeditionPublicCatalog():List<Achievement> = buildList {
    fun b(i:Int,t:String,d:String,g:BadgeGroup,r:Rarity,k:String,n:Double=1.0,u:String="") {
        add(Achievement("exp$i",t,d,g,r,k,n,u))
    }
    val c=Rarity.COMMON;val u=Rarity.UNCOMMON;val r=Rarity.RARE;val e=Rarity.EPIC;val l=Rarity.LEGENDARY
    b(1,"Две половины дня","В одном походе пройти по шагам по 2 км до 12:00 и после 16:00.",BadgeGroup.TIME,r,"expDayHalves")
    b(2,"Ритм экспедиции","Записать подряд 10 минут движения, 10 минут привала и ещё 10 минут движения, без пропусков.",BadgeGroup.ROUTE,u,"expWalkRestWalk")
    b(3,"Контур исследован","Замкнуть непрерывный GPS-контур: путь от 2 км, возвращение в 100 м от старта, площадь от 0,25 км².",BadgeGroup.GEO,e,"expAreaKm2",.25,"км²")
    b(4,"Четыре стороны одного дня","За один поход записать по 250 м GPS-пути на север, юг, запад и восток (секторы ±45°).",BadgeGroup.GEO,r,"expCardinals",4.0,"стороны")
    b(5,"Возвращение за находкой","После метки «Нашли» пройти по шагам 1 км и через 30 минут или позже вернуться к ней в 100 м. Нужен GPS, без пауз и разрывов.",BadgeGroup.ROUTE,e,"expFoundReturn")
    b(6,"Двойной выход","За один календарный день записать два отдельных похода: каждый от 2 км и 10 минут движения.",BadgeGroup.JOURNAL,u,"expDayOutings",2.0,"похода")
    b(7,"Из прохлады в тепло","В непрерывной записи измерить потепление от 5 °C за 30–90 минут.",BadgeGroup.WEATHER,u,"expWarmShift",5.0,"°C")
    b(8,"Другой воздух","В непрерывном окне 30–90 минут измерить изменение влажности от 30 п.п. и температуры от 3 °C.",BadgeGroup.WEATHER,r,"expAirChange",30.0,"п.п.")
    b(9,"Остывающий вечер","После рассчитанного заката измерить похолодание от 3 °C за 30–90 минут. Нужен достоверный GPS для расчёта заката.",BadgeGroup.WEATHER,r,"expEveningCool",3.0,"°C")
    b(10,"Барометр и гигрометр","За непрерывное окно 60–90 минут давление упало от 3 гПа, а влажность выросла от 15 п.п. Это измерения, не прогноз.",BadgeGroup.WEATHER,e,"expWeatherTogether")
    b(11,"Рассветный привал","После километра по шагам встретить рассчитанный восход на привале от 10 минут. Нужен GPS.",BadgeGroup.LIGHT,r,"expDawnRest")
    b(12,"Последний свет в кадре","Поставить хлопушку в пределах 15 минут от рассчитанного заката, с достоверной GPS-привязкой.",BadgeGroup.LIGHT,u,"expSunsetClap")
    b(13,"Личная традиция","Четыре недели подряд выходить в один и тот же день недели: от 1000 шагов или 1 км за день.",BadgeGroup.CALENDAR,e,"expWeeklyStreak",4.0,"недели")
    b(14,"Выходные с продолжением","Пройти за одну субботу и следующее воскресенье суммарно 10 км, не менее 1 км в каждый из двух дней.",BadgeGroup.CALENDAR,r,"expWeekendKm",10.0,"км")
    b(15,"Между страницами календаря","В одном походе записать по 500 шагов в последний день месяца и в следующий первый день.",BadgeGroup.CALENDAR,r,"expMonthBoundary")
    b(16,"Полевой блокнот","В одном походе поставить «Зашли», «Нашли» и текстовую заметку от 8 символов.",BadgeGroup.MARKS,c,"expFieldNotes")
    b(17,"Детали не забыты","Сохранить 10 разных текстовых меток длиной от 8 символов.",BadgeGroup.MARKS,c,"expNotes",10.0,"заметок")
    b(18,"Находка попала в кадр","За один поход сделать три пары «Нашли» → хлопушка в течение 5 минут; каждая метка используется один раз.",BadgeGroup.MARKS,u,"expFoundClaps",3.0,"пары")
    b(19,"Три точки интереса","За один поход поставить три метки «Нашли» с GPS, попарно не ближе 150 м.",BadgeGroup.MARKS,r,"expDistinctFound",3.0,"точки")
    b(20,"К исходной двери","После GPS-метки «Зашли» записать 500 шагов и через 15 минут или позже вернуться к ней в 100 м, без пауз и разрывов.",BadgeGroup.ROUTE,r,"expEntryReturn")
    b(21,"Журнал не потерялся","Записать непрерывный участок без достоверного GPS от 20 минут: не менее 500 шагов и двух меток.",BadgeGroup.SIGNAL,r,"expBlindJournal")
    b(22,"Мысли на привале","После километра по шагам сделать привал от 10 минут и оставить текстовую метку длиной от 20 символов.",BadgeGroup.MARKS,c,"expRestNote")
    b(23,"Съёмочные дни","Записать хлопушки в пяти разных календарных днях.",BadgeGroup.MARKS,u,"expCameraDays",5.0,"дней")
    b(24,"Знакомая точка","Поставить GPS-метки «Нашли» в одной и той же ячейке сетки около 500 м в три разных дня.",BadgeGroup.GEO,e,"expReturnDays",3.0,"дня")
    b(25,"Карта воспоминаний","Отметить «Нашли» в 20 разных ячейках сетки около 500 м, с достоверной GPS-привязкой.",BadgeGroup.GEO,e,"expFoundCells",20.0,"мест")
    val names=listOf("Выборгский вектор","Приозерская сторона","У истока Невы","Волховский след","Тихвинские дороги","Лужский выезд","Гатчинская тропа","Кингисеппское направление")
    ExpeditionPlaces.all.forEachIndexed {i,p ->
        b(26+i,names[i],"Прогуляться в окрестностях ${p.genitive}: 5 минут подряд и 100 шагов с достоверным GPS в радиусе 5 км от центра.",BadgeGroup.GEO,if(i in listOf(4,5,7))r else u,"expRegion:${p.id}")
    }
    b(34,"Три областных направления","Выполнить условия прогулки в трёх из восьми городских окрестностей этого набора.",BadgeGroup.GEO,e,"expRegions",3.0,"направления")
    b(35,"Областная коллекция","Выполнить условия прогулки во всех восьми городских окрестностях набора.",BadgeGroup.GEO,l,"expRegions",8.0,"направлений")
}

